{"implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    dp = {0: (0, 0, [])}  # weight -> ( -score, tokens, indices )
    for i in range(n):
        L = lengths[i]
        S = scores[i]
        newdp = dict(dp)
        for w, (neg_score, tokens, indices) in dp.items():
            if w + L <= budget:
                new_score = -neg_score + S
                new_tokens = tokens + L
                new_indices = indices + [i]
                new_key = (-new_score, new_tokens, new_indices)
                if w + L not in newdp or new_key < newdp[w + L]:
                    newdp[w + L] = new_key
        dp = newdp
    best_key = None
    for w, key in dp.items():
        if w <= budget:
            if best_key is None or key < best_key:
                best_key = key
    neg_score, used_tokens, selected_indices = best_key
    total_score = -neg_score
    return {
        "selected_indices": selected_indices,
        "used_tokens": used_tokens,
        "summed_score": total_score
    }"}
